1	"use client";
2	
3	import React from "react";
4	import { motion } from "framer-motion";
5	import { ArrowRight, ArrowUpRight } from "lucide-react";
6	import { BRAND, FONT, SHADOW } from "@/lib/brand";
7	import { ProductBreadcrumb } from "@/components/product/product-breadcrumb";
8	
9	interface ProductHeroProps {
10	  feature: string;
11	  headline: string;
12	  italicWord: string;
13	  subhead: string;
14	  primaryCTA?: { label: string; href: string };
15	  secondaryCTA?: { label: string; href: string };
16	  dashboard: React.ReactNode;
17	}
18	
19	const defaultPrimary = {
20	  label: "Start free trial",
21	  href: "https://inkos.up.railway.app/signup",
22	};
23	
24	const defaultSecondary = {
25	  label: "See it in motion",
26	  href: "/book-a-demo",
27	};
28	
29	function buildHeadlineParts(headline: string, italicWord: string) {
30	  const idx = headline.indexOf(italicWord);
31	  if (idx === -1) {
32	    return { before: headline, italic: "", after: "" };
33	  }
34	  return {
35	    before: headline.slice(0, idx),
36	    italic: italicWord,
37	    after: headline.slice(idx + italicWord.length),
38	  };
39	}
40	
41	export function ProductHero({
42	  feature,
43	  headline,
44	  italicWord,
45	  subhead,
46	  primaryCTA = defaultPrimary,
47	  secondaryCTA = defaultSecondary,
48	  dashboard,
49	}: ProductHeroProps) {
50	  const { before, italic, after } = buildHeadlineParts(headline, italicWord);
51	
52	  return (
53	    <section
54	      style={{
55	        background: BRAND.bone,
56	        position: "relative",
57	        overflow: "hidden",
58	        paddingTop: 140,
59	        paddingBottom: 80,
60	      } as React.CSSProperties}
61	    >
62	      {/* Background grid texture */}
63	      <div
64	        aria-hidden="true"
65	        style={{
66	          position: "absolute",
67	          inset: 0,
68	          opacity: 0.4,
69	          pointerEvents: "none",
70	          backgroundImage: `linear-gradient(${BRAND.border} 1px, transparent 1px), linear-gradient(90deg, ${BRAND.border} 1px, transparent 1px)`,
71	          backgroundSize: "80px 80px",
72	          maskImage:
73	            "radial-gradient(ellipse at 50% 30%, black 30%, transparent 70%)",
74	        } as React.CSSProperties}
75	      />
76	
77	      <div
78	        style={{
79	          maxWidth: 1280,
80	          margin: "0 auto",
81	          padding: "0 32px",
82	          position: "relative",
83	        } as React.CSSProperties}
84	      >
85	        <ProductBreadcrumb feature={feature} />
86	
87	        <div style={{ maxWidth: 920 } as React.CSSProperties}>
88	          <motion.h1
89	            initial={{ opacity: 0, y: 20 }}
90	            animate={{ opacity: 1, y: 0 }}
91	            transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
92	            style={{
93	              fontFamily: FONT.serif,
94	              fontSize: "clamp(56px, 8vw, 112px)",
95	              lineHeight: 0.95,
96	              letterSpacing: "-0.03em",
97	              color: BRAND.onyx,
98	              fontWeight: 400,
99	              marginBottom: 28,
100	              margin: "0 0 28px 0",
101	            } as React.CSSProperties}
102	          >
103	            {before}
104	            <span
105	              style={{
106	                fontStyle: "italic",
107	                color: BRAND.rust,
108	              } as React.CSSProperties}
109	            >
110	              {italic}
111	            </span>
112	            {after}
113	          </motion.h1>
114	
115	          <motion.p
116	            initial={{ opacity: 0, y: 16 }}
117	            animate={{ opacity: 1, y: 0 }}
118	            transition={{ duration: 0.65, delay: 0.12, ease: [0.22, 1, 0.36, 1] }}
119	            style={{
120	              fontFamily: FONT.sans,
121	              fontSize: 19,
122	              lineHeight: 1.55,
123	              color: BRAND.stoneDark,
124	              maxWidth: 720,
125	              marginBottom: 36,
126	            } as React.CSSProperties}
127	          >
128	            {subhead}
129	          </motion.p>
130	
131	          <motion.div
132	            initial={{ opacity: 0, y: 12 }}
133	            animate={{ opacity: 1, y: 0 }}
134	            transition={{ duration: 0.6, delay: 0.22, ease: [0.22, 1, 0.36, 1] }}
135	            style={{
136	              display: "flex",
137	              alignItems: "center",
138	              gap: 14,
139	              flexWrap: "wrap",
140	            } as React.CSSProperties}
141	          >
142	            <a
143	              href={primaryCTA.href}
144	              style={{
145	                display: "inline-flex",
146	                alignItems: "center",
147	                gap: 8,
148	                fontFamily: FONT.sans,
149	                fontSize: 15,
150	                fontWeight: 600,
151	                color: BRAND.bone,
152	                background: BRAND.onyx,
153	                padding: "14px 26px",
154	                borderRadius: 100,
155	                textDecoration: "none",
156	                letterSpacing: "-0.01em",
157	                boxShadow: SHADOW.card,
158	              } as React.CSSProperties}
159	            >
160	              {primaryCTA.label}
161	              <ArrowRight size={16} strokeWidth={2.2} />
162	            </a>
163	
164	            <a
165	              href={secondaryCTA.href}
166	              style={{
167	                display: "inline-flex",
168	                alignItems: "center",
169	                gap: 8,
170	                fontFamily: FONT.sans,
171	                fontSize: 15,
172	                fontWeight: 500,
173	                color: BRAND.onyx,
174	                background: "transparent",
175	                padding: "13px 22px",
176	                borderRadius: 100,
177	                textDecoration: "none",
178	                letterSpacing: "-0.01em",
179	                border: `1px solid ${BRAND.border}`,
180	              } as React.CSSProperties}
181	            >
182	              {secondaryCTA.label}
183	              <ArrowUpRight size={16} strokeWidth={2} />
184	            </a>
185	          </motion.div>
186	        </div>
187	
188	        <motion.div
189	          initial={{ opacity: 0, y: 40 }}
190	          animate={{ opacity: 1, y: 0 }}
191	          transition={{
192	            duration: 0.9,
193	            delay: 0.4,
194	            ease: [0.22, 1, 0.36, 1],
195	          }}
196	          style={{ marginTop: 80 } as React.CSSProperties}
197	        >
198	          {dashboard}
199	        </motion.div>
200	      </div>
201	    </section>
202	  );
203	}
